class Solution:
    def maximizeSum(self, nums: list[int], k: int) -> int:
        gains = []
        for value in nums:
            rearranged = int(''.join(sorted(str(value), reverse=True)))
            gains.append(rearranged - value)
        return sum(nums) + sum(sorted(gains, reverse=True)[:k])
